int addType(final String value) {
    if (value == null) {
        throw new IllegalArgumentException("Type value cannot be null");
    }

    // Check if the type already exists in the type table
    for (int i = 0; i < typeTable.size(); i++) {
        if (typeTable.get(i).getValue().equals(value)) {
            return i;
        }
    }

    // If not found, add the new type
    typeTable.add(new Symbol(value));
    return typeTable.size() - 1;
}

