private void pop(final String descriptor) {
    if (descriptor == null) {
        throw new IllegalArgumentException("Descriptor must not be null");
    }

    int count = 0;
    int i = 0;
    int len = descriptor.length();

    // If it's a method descriptor, skip the opening parenthesis
    if (i < len && descriptor.charAt(i) == '(') {
        i++;
    }

    while (i < len) {
        char c = descriptor.charAt(i);
        if (c == ')') {
            break;
        }

        switch (c) {
            case 'B': // boolean
            case 'C': // char
            case 'D': // double
            case 'F': // float
            case 'I': // int
            case 'J': // long
            case 'S': // short
            case 'Z': // boolean
                count++;
                i++;
                break;
            case 'L': // object reference
                count++;
                i++;
                // Skip until ';'
                while (i < len && descriptor.charAt(i) != ';') {
                    i++;
                }
                if (i < len) {
                    i++; // skip ';'
                }
                break;
            case '[': // array
                i++;
                break;
            default:
                throw new IllegalArgumentException("Invalid descriptor character: " + c);
        }
    }

    // Pop the required number of types from the output frame stack
    for (int j = 0; j < count; j++) {
        if (outputFrameStack.isEmpty()) {
            throw new IllegalStateException("Output frame stack is empty, cannot pop " + count + " types");
        }
        outputFrameStack.pop();
    }
}

