static String[] toNoNullStringArray(Object[] array) {
    if (array == null) {
        return new String[0];
    }

    // First pass: count non-null elements
    int count = 0;
    for (Object obj : array) {
        if (obj != null) {
            count++;
        }
    }

    // If all elements are non-null, we can return the original array cast to String[]
    // But we need to be careful - the array might contain non-String objects
    // Let's create a new array with only non-null String elements

    String[] result = new String[count];
    int index = 0;
    for (Object obj : array) {
        if (obj != null) {
            if (obj instanceof String) {
                result[index++] = (String) obj;
            } else {
                // Convert non-String objects to String
                result[index++] = obj.toString();
            }
        }
    }

    return result;
}

