    if (tour == null || graph == null) {
        throw new IllegalArgumentException("Tour and graph must not be null");
    }

    if (tour.isEmpty()) {
        return new GraphPathImpl<>(graph, new ArrayList<>(), new ArrayList<>());
    }

    // Find a starting vertex
    V startVertex = null;
    for (E edge : tour) {
        if (graph.getEdgeSource(edge) != null) {
            startVertex = graph.getEdgeSource(edge);
            break;
        }
    }

    if (startVertex == null) {
        // If no source found, try target
        for (E edge : tour) {
            if (graph.getEdgeTarget(edge) != null) {
                startVertex = graph.getEdgeTarget(edge);
                break;
            }
        }
    }

    if (startVertex == null) {
        return new GraphPathImpl<>(graph, new ArrayList<>(), new ArrayList<>());
    }

    List<V> vertexPath = new ArrayList<>();
    List<E> edgePath = new ArrayList<>();

    vertexPath.add(startVertex);
    V currentVertex = startVertex;
    Set<E> remainingEdges = new HashSet<>(tour);

    while (!remainingEdges.isEmpty()) {
        E nextEdge = null;
        V nextVertex = null;

        // Find an edge from currentVertex that is in the remaining set
        for (E edge : remainingEdges) {
            if (graph.getEdgeSource(edge).equals(currentVertex)) {
                nextEdge = edge;
                nextVertex = graph.getEdgeTarget(edge);
                break;
            } else if (graph.getEdgeTarget(edge).equals(currentVertex)) {
                nextEdge = edge;
                nextVertex = graph.getEdgeSource(edge);
                break;
            }
        }

        if (nextEdge == null) {
            // No edge found from current vertex, break
            break;
        }

        edgePath.add(nextEdge);
        vertexPath.add(nextVertex);
        remainingEdges.remove(nextEdge);
        currentVertex = nextVertex;
    }

    return new GraphPathImpl<>(graph, vertexPath, edgePath);
}

