        throw new IllegalArgumentException("vertices must not be null");
    }
    if (graph == null) {
        throw new IllegalArgumentException("graph must not be null");
    }
    // A clique of size 0 or 1 is trivially a clique
    if (vertices.size() <= 1) {
        return true;
    }
    // For each pair of distinct vertices, check if there is an edge between them
    for (V v1 : vertices) {
        for (V v2 : vertices) {
            if (v1.equals(v2)) {
                continue;
            }
            if (!graph.containsEdge(v1, v2)) {
                return false;
            }
        }
    }
    return true;
}

