static long compressTimeBucket(long timeBucket, int dayStep) {
    if (dayStep <= 0) {
        throw new IllegalArgumentException("dayStep must be positive");
    }
    // Extract year, month, day from timeBucket (format: YYYYMMDD)
    int year = (int) (timeBucket / 10000);
    int month = (int) ((timeBucket % 10000) / 100);
    int day = (int) (timeBucket % 100);

    // Validate month and day
    if (month < 1 || month > 12) {
        throw new IllegalArgumentException("Invalid month: " + month);
    }
    if (day < 1 || day > 31) {
        throw new IllegalArgumentException("Invalid day: " + day);
    }

    // Calculate the start of the current dayStep period
    // The period starts at day 1, then 1+dayStep, 1+2*dayStep, etc.
    // We need to find the largest start day such that start <= day
    // start = 1 + k * dayStep, where k is the largest integer such that 1 + k*dayStep <= day
    // k = (day - 1) / dayStep (integer division)
    int k = (day - 1) / dayStep;
    int startDay = 1 + k * dayStep;

    // Construct the compressed time bucket
    return year * 10000L + month * 100L + startDay;
}

