public static LinkedBuffer writeUTF8(final CharSequence str, final WriteSession session, final LinkedBuffer lb) {
    if (str == null) {
        throw new NullPointerException("str must not be null");
    }
    if (session == null) {
        throw new NullPointerException("session must not be null");
    }
    if (lb == null) {
        throw new NullPointerException("lb must not be null");
    }

    int length = str.length();
    if (length == 0) {
        return lb;
    }

    // Estimate the number of bytes needed for UTF-8 encoding
    int estimatedBytes = length;
    for (int i = 0; i < length; i++) {
        char c = str.charAt(i);
        if (c > 0x7F) {
            if (c > 0x7FF) {
                estimatedBytes += 2;
            } else {
                estimatedBytes += 1;
            }
        }
    }

    // Ensure the buffer has enough space
    if (lb.capacity() < estimatedBytes) {
        lb.ensureCapacity(estimatedBytes);
    }

    // Write the UTF-8 encoded bytes
    int offset = lb.offset();
    for (int i = 0; i < length; i++) {
        char c = str.charAt(i);
        if (c <= 0x7F) {
            lb.writeByte((byte) c);
        } else if (c <= 0x7FF) {
            lb.writeByte((byte) (0xC0 | (c >> 6)));
            lb.writeByte((byte) (0x80 | (c & 0x3F)));
        } else {
            lb.writeByte((byte) (0xE0 | (c >> 12)));
            lb.writeByte((byte) (0x80 | ((c >> 6) & 0x3F)));
            lb.writeByte((byte) (0x80 | (c & 0x3F)));
        }
    }

    return lb;
}

