        return new byte[0];
    }

    int totalLength = 0;
    for (ByteBuffer buffer : buffers) {
        if (buffer != null) {
            totalLength += buffer.remaining();
        }
    }

    byte[] result = new byte[totalLength];
    int offset = 0;
    for (ByteBuffer buffer : buffers) {
        if (buffer != null) {
            int remaining = buffer.remaining();
            if (remaining > 0) {
                buffer.get(result, offset, remaining);
                offset += remaining;
            }
        }
    }

    return result;
}

